// Servicio de bases de datos que elige un asistente para cinco casos. Corrige la elección equivocada.
export const eleccion = {
  casos: [
    { necesidad: "Guardar los carritos de compra como elementos de clave-valor", servicio: "dynamodb" },
    { necesidad: "Ejecutar una aplicación de pedidos con MySQL sin gestionar parches ni copias", servicio: "rds" },
    { necesidad: "Analizar años de ventas con SQL desde herramientas de inteligencia de negocio", servicio: "redshift" },
    { necesidad: "Guardar en memoria los datos más consultados para acelerar la aplicación", servicio: "elasticache" },
    { necesidad: "Usar un motor compatible con PostgreSQL con almacenamiento distribuido que crece solo", servicio: "aurora" },
  ],
};

spec.code:
const fila = eleccion.casos.find((f) => f.necesidad.startsWith("Guardar en memoria"));
assert.ok(fila, "debe existir la fila de los datos en memoria");
assert.strictEqual(fila.servicio, "elasticache");

for (const fila of eleccion.casos) {
  assert.ok(["rds", "aurora", "dynamodb", "elasticache", "redshift"].includes(fila.servicio), fila.necesidad + " tiene un servicio no válido");
}

const esperado = {
  "Guardar los carritos de compra como elementos de clave-valor": "dynamodb",
  "Ejecutar una aplicación de pedidos con MySQL sin gestionar parches ni copias": "rds",
  "Analizar años de ventas con SQL desde herramientas de inteligencia de negocio": "redshift",
  "Usar un motor compatible con PostgreSQL con almacenamiento distribuido que crece solo": "aurora",
};
for (const [necesidad, servicio] of Object.entries(esperado)) {
  const fila = eleccion.casos.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}
